import{_ as s,o as t,c as a,a2 as o}from"./chunks/framework.BM5YPQmL.js";const u=JSON.parse('{"title":"Network troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"troubleshooting/network-issues.md","filePath":"troubleshooting/network-issues.md"}'),n={name:"troubleshooting/network-issues.md"};function i(r,e,l,c,d,h){return t(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="network-troubleshooting" tabindex="-1">Network troubleshooting <a class="header-anchor" href="#network-troubleshooting" aria-label="Permalink to &quot;Network troubleshooting&quot;">​</a></h1><h2 id="ordered-triage" tabindex="-1">Ordered triage <a class="header-anchor" href="#ordered-triage" aria-label="Permalink to &quot;Ordered triage&quot;">​</a></h2><p>Run <code>net-tool</code> and walk the menu, or use the classic spellings:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; hwinfo                 (wizard: PCI page - is the NIC on the bus?)</span></span>
<span class="line"><span>ush&gt; ip                     (address bound? 0.0.0.0 = none)</span></span>
<span class="line"><span>ush&gt; dhcp                   (address + gateway + DNS in one shot)</span></span>
<span class="line"><span>ush&gt; ping 10.0.2.2          (ICMP to the QEMU gateway)</span></span>
<span class="line"><span>ush&gt; arp                    (L2 resolution happened?)</span></span>
<span class="line"><span>ush&gt; dns example.com        (UDP + resolver OK?)</span></span>
<span class="line"><span>ush&gt; wget example.com 80 /  (full TCP + HTTP round trip)</span></span>
<span class="line"><span>ush&gt; tcpstats               (per-connection counters)</span></span></code></pre></div><p>Each step isolates a layer: bus -&gt; driver -&gt; L2 -&gt; L3 -&gt; L4 -&gt; application. The <code>update</code> wizard runs the first steps of exactly this ladder (IP -&gt; DHCP fix -&gt; DNS) before it ever checks for updates.</p><h2 id="qemu-specifics" tabindex="-1">QEMU specifics <a class="header-anchor" href="#qemu-specifics" aria-label="Permalink to &quot;QEMU specifics&quot;">​</a></h2><ul><li>User-mode networking always provides 10.0.2.2 (gateway) and DNS forwarding - no host configuration needed.</li><li>The default <code>-device e1000</code> is the best-tested path.</li><li>Two-instance tests: shared <code>-netdev socket/multicast</code> gives a real two-node link for the NIC tests.</li><li><strong>First connect to sshd stalls</strong>: the ARP cache is cold after DHCP - run one client-direction command first (<code>ping</code> the peer) to warm it.</li></ul><h2 id="tls-ssh-specifics" tabindex="-1">TLS/SSH specifics <a class="header-anchor" href="#tls-ssh-specifics" aria-label="Permalink to &quot;TLS/SSH specifics&quot;">​</a></h2><ul><li>Certificate failures print the exact verification stage (chain/hostname/policy) - read the message; the trust model (un-anchored warns, mismatch is fatal for named hosts) is in <a href="./../arch/network-stack.html">arch/network-stack.md</a>.</li><li>sshd host keys: generate on first boot, or pre-seed <code>ssh_host_key</code> on the /etc volume (<code>tools/host_keygen_etc.py</code>, or the mtools recipe in <a href="./../dev/e2e-suites.html">../dev/e2e-suites.md</a>) <ul><li>the E2E suite&#39;s prerequisite.</li></ul></li></ul>`,9)])])}const g=s(n,[["render",i]]);export{u as __pageData,g as default};
